-- 0057_catalogo_moduli : il catalogo dei moduli, da 23 a 88 modelli
--
-- Il catalogo aveva un solo modello per rarita' e categoria: 23 in tutto, e
-- due moduli trovati erano quasi sempre lo stesso. Ora 18 famiglie, ognuna con
-- una funzione precisa e un modello per ogni rarita' (l'occultamento solo dalle
-- tre piu' alte). Sette effetti sono nuovi: tetto dei caccia, interdizione,
-- corazza, schermatura ambientale, elusione, disturbo elettronico, transponder
-- e fabbrica di caccia a bordo. I modelli esistenti mantengono la chiave; alcuni
-- cambiano valori per stare nella progressione della loro famiglia (i moduli
-- gia' posseduti conservano i valori con cui sono stati trovati).

ON DUPLICATE KEY UPDATE name = VALUES(name), category = VALUES(category), family = VALUES(family),
  rarity = VALUES(rarity), effects = VALUES(effects), base_salvage = VALUES(base_salvage),
  descr = IF(descr IS NULL OR descr = '', VALUES(descr), descr), sort_order = VALUES(sort_order);
